/**
 * Bulk issue import: the replay ledger (one row per workspace import key) and the
 * all-or-nothing batch write behind `importIssues`.
 *
 * Must call (do not reimplement): orgPredicate, toIssue, parseJsonArray, newId
 */
import { and, eq, sql } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, issueImports, issueLabels, issues, labels } from "@/server/db";
import type { IssueImportRow } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import type {
  IsoTimestamp,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue, IssuePriority, IssueStatus } from "@/types/issue";
import { parseJsonArray, toIssue } from "./_mappers";
import { orgPredicate } from "./base-repository";

/** One import row with its assignee already resolved to a member and its labels named. */
export interface ImportBatchRow {
  readonly title: string;
  readonly description: string | null;
  readonly status: IssueStatus;
  readonly priority: IssuePriority;
  readonly assigneeId: UserId | null;
  readonly dueAt: IsoTimestamp | null;
  readonly labelNames: readonly string[];
}

/** What a finished import left in the ledger: its project and its issues in file order. */
export interface IssueImportRecord {
  readonly projectId: ProjectId;
  readonly issueIds: readonly IssueId[];
}

export type IssueImportWrite =
  | (IssueImportRecord & { readonly replayed: true })
  | { readonly replayed: false; readonly issues: readonly Issue[] };

export interface InsertIssueImportInput {
  readonly orgId: OrgId;
  readonly projectId: ProjectId;
  readonly importKey: string;
  readonly authorId: UserId;
  readonly rows: readonly ImportBatchRow[];
}

export async function findIssueImport(
  orgId: OrgId,
  importKey: string,
): Promise<IssueImportRecord | null> {
  const row = getDb()
    .select()
    .from(issueImports)
    .where(
      and(
        orgPredicate(issueImports.orgId, orgId),
        eq(issueImports.importKey, importKey),
      ),
    )
    .get();
  return row ? toImportRecord(row) : null;
}

function toImportRecord(row: IssueImportRow): IssueImportRecord {
  return {
    projectId: row.projectId as ProjectId,
    issueIds: parseJsonArray<IssueId>(row.issueIds),
  };
}

/**
 * Writes a whole import inside one SQLite transaction, so the issues, their
 * label links and the ledger row either all land or none do. The ledger is
 * checked again inside the transaction so two uploads of one key cannot both
 * insert. Numbers continue after the highest number the project has ever used,
 * archived rows included, and follow file order.
 */
export async function insertIssueImport(
  input: InsertIssueImportInput,
): Promise<IssueImportWrite> {
  return getDb().transaction((tx) => {
    const prior = tx
      .select()
      .from(issueImports)
      .where(
        and(
          orgPredicate(issueImports.orgId, input.orgId),
          eq(issueImports.importKey, input.importKey),
        ),
      )
      .get();
    if (prior) return { ...toImportRecord(prior), replayed: true as const };

    const labelIds = new Map<string, LabelId>(
      tx
        .select()
        .from(labels)
        .where(orgPredicate(labels.orgId, input.orgId))
        .all()
        .map((label): [string, LabelId] => [label.name, label.id as LabelId]),
    );

    const top = tx
      .select({ value: sql<number | null>`max(${issues.number})` })
      .from(issues)
      .where(
        and(
          orgPredicate(issues.orgId, input.orgId),
          eq(issues.projectId, input.projectId),
        ),
      )
      .get();
    let number = top?.value ?? 0;

    const stamp = toIsoTimestamp(new Date());
    const created: Issue[] = [];

    for (const row of input.rows) {
      const rowLabelIds: LabelId[] = [];
      for (const name of new Set(row.labelNames)) {
        let labelId = labelIds.get(name);
        if (labelId === undefined) {
          labelId = newId() as LabelId;
          // Column defaults supply the colour; no description.
          tx.insert(labels)
            .values({
              id: labelId,
              orgId: input.orgId,
              name,
              createdAt: stamp,
              updatedAt: stamp,
            })
            .run();
          labelIds.set(name, labelId);
        }
        rowLabelIds.push(labelId);
      }

      number += 1;
      const issueRow = tx
        .insert(issues)
        .values({
          id: newId(),
          orgId: input.orgId,
          projectId: input.projectId,
          number,
          title: row.title,
          description: row.description,
          status: row.status,
          priority: row.priority,
          authorId: input.authorId,
          assigneeId: row.assigneeId,
          parentId: null,
          estimate: null,
          dueAt: row.dueAt,
          startedAt: null,
          completedAt: null,
          createdAt: stamp,
          updatedAt: stamp,
        })
        .returning()
        .get();

      if (rowLabelIds.length > 0) {
        tx.insert(issueLabels)
          .values(
            rowLabelIds.map((labelId) => ({
              orgId: input.orgId,
              issueId: issueRow.id,
              labelId,
            })),
          )
          .run();
      }
      created.push(toIssue(issueRow, rowLabelIds));
    }

    tx.insert(issueImports)
      .values({
        id: newId(),
        orgId: input.orgId,
        importKey: input.importKey,
        projectId: input.projectId,
        importedBy: input.authorId,
        issueIds: JSON.stringify(created.map((issue) => issue.id)),
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();

    return { replayed: false as const, issues: created };
  });
}

