/**
 * Batched read in the order of `issueIds`. Archived rows are included: a
 * replayed import returns the issues it created, whatever has happened to them since.
 */
export async function listIssuesByIds(
  orgId: OrgId,
  issueIds: readonly IssueId[],
): Promise<readonly Issue[]> {
  if (issueIds.length === 0) return [];

  const rows = getDb()
    .select()
    .from(issues)
    .where(
      and(orgPredicate(issues.orgId, orgId), inArray(issues.id, [...issueIds])),
    )
    .all();

  const labels = await listLabelsForIssues(
    orgId,
    rows.map((row) => row.id as IssueId),
  );
  const byId = new Map(rows.map((row) => [row.id, row] as const));

  return issueIds.flatMap((issueId) => {
    const row = byId.get(issueId);
    if (!row) return [];
    return [toIssue(row, (labels[row.id] ?? []).map((label) => label.id))];
  });
}

/** Builds the shared predicate list behind `listIssues` and its count. */

