    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    authorId: actor.userId,
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (assignees.get(row.assigneeEmail.toLowerCase()) ?? null),
      dueAt: row.dueAt,
      labelNames: row.labels,
    })),
  });
  if (write.replayed) return replayedImport(input, write);

  await emit("issues.imported", {
    ...actorEnvelope(actor),
    projectId: input.projectId,
    importKey: input.importKey,
    issueIds: write.issues.map((issue) => issue.id),
  });

  return {
    importKey: input.importKey,
    projectId: input.projectId,
    issues: write.issues,
    replayed: false,
  };
}

/** The first import's result, re-read: the same issues in the same order, nothing written. */
async function replayedImport(
  input: ImportIssuesInput,
  record: IssueImportRecord,
): Promise<IssueImportResult> {
  return {
    importKey: input.importKey,
    projectId: record.projectId,
    issues: await issueRepo.listIssuesByIds(input.orgId, record.issueIds),
    replayed: true,
  };
}

/**
 * Maps each email to the workspace member it belongs to, if that member is
 * active. Unknown addresses, non-members, removed and suspended members are
 * left out, so their rows are simply unassigned.
 */
async function resolveAssignees(
  orgId: OrgId,
  emails: readonly string[],
): Promise<ReadonlyMap<string, UserId>> {
  const resolved = new Map<string, UserId>();
  for (const email of new Set(emails.map((value) => value.toLowerCase()))) {
    const user = await userRepo.findUserByEmail(email);
    if (!user) continue;
    const member = await memberRepo.findMember(orgId, user.id);
    if (member?.status === "active") resolved.set(email, user.id);
  }
  return resolved;
}

