let other: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends keyof TaskflowEventMap>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function row(
  title: string,
  overrides: Partial<ImportIssueRowInput> = {},
): ImportIssueRowInput {
  return {
    title,
    description: null,
    status: "backlog",
    priority: "none",
    assigneeEmail: null,
    labels: [],
    dueAt: null,
    ...overrides,
  };
}

function batch(
  target: Tenant,
  rows: readonly ImportIssueRowInput[],
  importKey: string,
  projectId: ProjectId = target.project.id,
): ImportIssuesInput {
  return { orgId: target.org.id, projectId, importKey, rows };
}

function countAll(target: Tenant): Promise<number> {
  return issueRepo.countIssues(target.org.id, target.project.id, {
    includeArchived: true,
  });
}

