import * as projectService from "@/server/services/project-service";
import * as searchService from "@/server/services/search-service";
import * as usageService from "@/server/services/usage-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { ProjectId } from "@/types/common";
import type { TaskflowEventMap, Unsubscribe } from "@/types/event";

let cleanup: () => void;
let tenant: Tenant;
let other: Tenant;
const detachers: Unsubscribe[] = [];

/** Collects every payload delivered for one event type during a test. */
function capture<K extends keyof TaskflowEventMap>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

function row(
  title: string,
  overrides: Partial<ImportIssueRowInput> = {},
): ImportIssueRowInput {
  return {
    title,
    description: null,
    status: "backlog",
    priority: "none",
    assigneeEmail: null,
    labels: [],
    dueAt: null,
    ...overrides,
  };
}

function batch(
  target: Tenant,
  rows: readonly ImportIssueRowInput[],
  importKey: string,
  projectId: ProjectId = target.project.id,
): ImportIssuesInput {
  return { orgId: target.org.id, projectId, importKey, rows };
}

function countAll(target: Tenant): Promise<number> {
  return issueRepo.countIssues(target.org.id, target.project.id, {
    includeArchived: true,
  });
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerEventHandlers();
  tenant = await createTenant("importer");
  other = await createTenant("elsewhere");
});

afterEach(() => {
  while (detachers.length > 0) detachers.pop()?.();
});

afterAll(() => {
  unregisterEventHandlers();
  cleanup();
});

describe("importIssues: access", () => {
  it("refuses an actor without issue:create and writes nothing", async () => {
    const before = await countAll(tenant);

    await expect(
      issueService.importIssues(
        tenant.actors.viewer,
        batch(tenant, [row("Viewer tries")], "viewer-key-01"),
      ),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    expect(await countAll(tenant)).toBe(before);
  });

  it("refuses an orgId outside the actor's workspace", async () => {
    await expect(
      issueService.importIssues(
        tenant.actors.owner,
        batch(other, [row("Cross workspace")], "cross-key-01"),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("reports an unknown project, or another workspace's project, as not found", async () => {
    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant, [row("Ghost")], "ghost-key-01", newId() as ProjectId),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant, [row("Foreign")], "foreign-key-01", other.project.id),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("refuses an archived project", async () => {
    const retired = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Retired",
      slug: "retired",
      key: "RET",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await projectService.archiveProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      projectId: retired.id,
      archiveIssues: false,
    });

    await expect(
      issueService.importIssues(
        tenant.actors.member,
        batch(tenant, [row("Too late")], "retired-key-01", retired.id),
      ),
    ).rejects.toBeInstanceOf(AlreadyArchivedError);
  });
});

describe("importIssues: rows and numbering", () => {
  it("keeps the given fields, attributes the importer, and leaves parent and estimate empty", async () => {
    const dueAt = "2026-11-01T09:00:00.000Z" as ImportIssueRowInput["dueAt"];

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(
        tenant,
        [row("Exact fields", { description: "Body text", status: "in_review", priority: "high", dueAt })],
        "fields-key-01",
      ),
    );

    expect(result.replayed).toBe(false);
    expect(result.issues[0]).toMatchObject({
      title: "Exact fields",
      description: "Body text",
      status: "in_review",
      priority: "high",
      dueAt,
      authorId: tenant.userIds.member,
      assigneeId: null,
      parentId: null,
      estimate: null,
    });
  });

  it("numbers rows in file order after the highest number ever used, archived rows included", async () => {
    const numbering = await projectService.createProject(tenant.actors.admin, {
      orgId: tenant.org.id,
      name: "Numbering",
      slug: "numbering",
      key: "NUM",
      description: null,
      visibility: "org",
      leadId: null,
      color: "#6366f1",
      targetDate: null,
    });
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, numbering.id, { title: "Before one" }),
    );
    const second = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, numbering.id, { title: "Before two" }),
    );
    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, second.id);

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(
        tenant,
        [row("Numbered A"), row("Numbered B"), row("Numbered C")],
        "numbering-key-01",
        numbering.id,
      ),
    );

    expect(result.issues.map((issue) => issue.number)).toEqual([3, 4, 5]);
    expect(result.issues.map((issue) => issue.title)).toEqual([
      "Numbered A",
      "Numbered B",
      "Numbered C",
    ]);

    const after = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, numbering.id, { title: "After import" }),
    );
    expect(after.number).toBe(6);
  });
});

describe("importIssues: assignees and labels", () => {
  it("assigns by email, case-insensitively, to active members only", async () => {
    const removedUser = await userRepo.insertUser({
      email: "removed@importer.test",
      name: "Removed",
      passwordHash: "seed",
    });
    const removed = await memberRepo.insertMember(tenant.org.id, removedUser.id, "member", null);
    await memberRepo.archiveMember(tenant.org.id, removed.id);
    await userRepo.insertUser({
      email: "outsider@elsewhere.test",
      name: "Outsider",
      passwordHash: "seed",
    });

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(
        tenant,
        [
          row("Assign admin", { assigneeEmail: "ADMIN@Importer.TEST" }),
          row("Assign outsider", { assigneeEmail: "outsider@elsewhere.test" }),
          row("Assign removed", { assigneeEmail: "removed@importer.test" }),
          row("Assign nobody", { assigneeEmail: "nobody@nowhere.test" }),
        ],
        "assignee-key-01",
      ),
    );

    expect(result.issues.map((issue) => issue.assigneeId)).toEqual([
      tenant.userIds.admin,
      null,
      null,
      null,
    ]);
  });

  it("creates each missing label once, matches names exactly, and counts a repeated name once", async () => {
    await labelRepo.insertLabel({
      orgId: tenant.org.id,
      name: "bug",
      color: "#ff0000",
      description: null,
    });

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(
        tenant,
        [
          row("Label rows one", { labels: ["bug", "Bug", "triage-later", "triage-later"] }),
          row("Label rows two", { labels: ["triage-later"] }),
        ],
        "labels-key-01",
      ),
    );

    const all = await labelRepo.listLabels(tenant.org.id);
    const named = new Map(all.map((label) => [label.name, label]));

    expect(named.get("bug")?.color).toBe("#ff0000");
    expect(named.get("Bug")).toMatchObject({ color: "#94a3b8", description: null });
    expect(all.filter((label) => label.name === "triage-later")).toHaveLength(1);

    const triage = named.get("triage-later")?.id;
    expect(result.issues[0]?.labelIds).toEqual([
      named.get("bug")?.id,
      named.get("Bug")?.id,
      triage,
    ]);
    expect(result.issues[1]?.labelIds).toEqual([triage]);

    const otherLabels = await labelRepo.listLabels(other.org.id);
    expect(otherLabels.map((label) => label.name)).not.toContain("triage-later");
  });
});

describe("importIssues: events, audit, search and usage", () => {
  it("publishes one issues.imported for the batch and no issue.created", async () => {
    const batchEvents = capture("issues.imported");
    const created = capture("issue.created");

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [row("Batch alpha"), row("Batch bravo")], "batch-key-01"),
    );

    expect(created).toHaveLength(0);
    expect(batchEvents).toHaveLength(1);
    expect(batchEvents[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.member,
      projectId: tenant.project.id,
      importKey: "batch-key-01",
      issueIds: result.issues.map((issue) => issue.id),
    });
  });

  it("writes one audit entry, makes issues searchable, and moves the usage meter by the batch", async () => {
    const before = await usageService.recomputeUsage(tenant.org.id);

    const result = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [row("Audit charlie"), row("Audit delta")], "audit-key-01"),
    );

    const after = await usageService.getUsage(tenant.actors.owner, tenant.org.id);
    expect(after.issuesUsed - before.issuesUsed).toBe(2);
    const recount = await usageService.recomputeUsage(tenant.org.id);
    expect(recount.issuesUsed).toBe(after.issuesUsed);

    const page = await activityService.listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["issues.imported"],
      limit: 50,
      cursor: null,
    });
    const entries = page.items.filter(
      (event) => event.metadata.importKey === "audit-key-01",
    );
    expect(entries).toHaveLength(1);
    expect(entries[0]).toMatchObject({
      action: "issues.imported",
      actorId: tenant.userIds.member,
      subjectKind: "project",
      subjectId: tenant.project.id,
      projectId: tenant.project.id,
      metadata: { count: 2, importKey: "audit-key-01" },
    });

    const perIssue = await activityService.listActivity(tenant.actors.owner, {
      orgId: tenant.org.id,
      action: ["issue.created"],
      limit: 200,
      cursor: null,
    });
    const importedIds = new Set<string>(result.issues.map((issue) => issue.id));
    expect(perIssue.items.filter((event) => importedIds.has(event.subjectId))).toHaveLength(0);

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "Audit charlie",
      kinds: ["issue"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.map((hit) => hit.title)).toContain("Audit charlie");
  });
});

describe("importIssues: replays", () => {
  it("returns the first import's issues in order and creates and publishes nothing", async () => {
    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [row("Replay one"), row("Replay two")], "replay-key-01"),
    );
    const countBefore = await countAll(tenant);
    const created = capture("issue.created");
    const batchEvents = capture("issues.imported");

    const replay = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [row("Rows changed"), row("Entirely different")], "replay-key-01"),
    );

    expect(first.replayed).toBe(false);
    expect(replay.replayed).toBe(true);
    expect(replay.issues.map((issue) => issue.id)).toEqual(first.issues.map((issue) => issue.id));
    expect(replay.issues.map((issue) => issue.title)).toEqual(["Replay one", "Replay two"]);
    expect(await countAll(tenant)).toBe(countBefore);
    expect(created).toHaveLength(0);
    expect(batchEvents).toHaveLength(0);
  });

  it("treats a different key as a new import, and a key used elsewhere as unrelated", async () => {
    const first = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [row("Same rows")], "same-rows-a"),
    );
    const second = await issueService.importIssues(
      tenant.actors.member,
      batch(tenant, [row("Same rows")], "same-rows-b"),
    );
    const elsewhere = await issueService.importIssues(
      other.actors.member,
      batch(other, [row("Same rows")], "same-rows-a"),
    );

    expect(second.replayed).toBe(false);
    expect(second.issues[0]?.id).not.toBe(first.issues[0]?.id);
    expect(elsewhere.replayed).toBe(false);
  });
});

describe("importIssues: plan quota and rate allowance", () => {
  it("refuses the whole batch when it would pass the project's plan quota", async () => {
    const full = await createTenant("importquota", "free");
    for (let number = 1; number <= 99; number += 1) {
      await issueRepo.insertIssue(
        issueInput(full.org.id, full.project.id, { title: `Seed ${number}` }),
        full.actors.member.userId,
        number,
      );
    }

    await expect(
      issueService.importIssues(
        full.actors.member,
        batch(full, [row("Over one"), row("Over two")], "quota-key-01"),
      ),
    ).rejects.toThrow(/allows no more issues/);
    expect(await countAll(full)).toBe(99);

    const fits = await issueService.importIssues(
      full.actors.member,
      batch(full, [row("Fits")], "quota-key-01"),
    );
    expect(fits.replayed).toBe(false);
    expect(fits.issues).toHaveLength(1);
  });

  it("spends one unit of the rate allowance per row and refuses a batch it cannot cover", async () => {
    const fresh = await createTenant("importrate", "free");
    const rows = Array.from({ length: 61 }, (_, index) => row(`Bulk row ${index}`));

    await expect(
      issueService.importIssues(fresh.actors.member, batch(fresh, rows, "rate-key-01")),
    ).rejects.toThrow(/rate limit/i);
    expect(await countAll(fresh)).toBe(0);

    const accepted = await issueService.importIssues(
      fresh.actors.member,
      batch(fresh, rows.slice(0, 60), "rate-key-01"),
    );
    expect(accepted.issues).toHaveLength(60);
  });
});

