/**
 * Bulk import of one file's rows into a project, all or nothing. Gates, in
 * order: tenant scope, a live project, `issue:create`, the import ledger (a key
 * this workspace has already used replays its first result and writes nothing),
 * the per-project quota, then the rate allowance at one unit per row. Only then
 * is anything written, and one `issues.imported` event covers the whole batch.
 */
export async function importIssues(
  actor: Actor,
  input: ImportIssuesInput,
): Promise<IssueImportResult> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const prior = await issueImportRepo.findIssueImport(input.orgId, input.importKey);
  if (prior) return replayedImport(input, prior);

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  // Archived issues occupy the quota, as they do for a single create.
  const used = await issueRepo.countIssues(input.orgId, input.projectId, {
    includeArchived: true,
  });
  if (wouldExceedLimit(org.plan, "issuesPerProject", used, input.rows.length)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const verdict = await consumeRateLimit(
    input.orgId,
    ISSUE_CREATE_BUCKET,
    input.rows.length,
  );
  if (!verdict.allowed) {
    throw new Error(
      `Issue creation rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const assignees = await resolveAssignees(
    input.orgId,
    input.rows.flatMap((row) =>
      row.assigneeEmail === null ? [] : [row.assigneeEmail],
    ),
  );

  const write = await issueImportRepo.insertIssueImport({
    orgId: input.orgId,
    projectId: input.projectId,
    importKey: input.importKey,
    authorId: actor.userId,
    rows: input.rows.map((row) => ({
      title: row.title,
      description: row.description,
      status: row.status,
      priority: row.priority,
      assigneeId:
        row.assigneeEmail === null
          ? null
          : (assignees.get(row.assigneeEmail.toLowerCase()) ?? null),
      dueAt: row.dueAt,
      labelNames: row.labels,
    })),
